param([Parameter(Mandatory)][string]$RuntimeRoot,[Parameter(Mandatory)][string]$StorageRoot,[Parameter(Mandatory)][string]$ExpectedExe,[Parameter(Mandatory)][string]$OutputRoot)
$ErrorActionPreference='Stop';$end=[datetime]::UtcNow.AddSeconds(1050)
try{
 $receipt=$null;while(!$receipt -and [datetime]::UtcNow -lt $end -and !(Test-Path "$StorageRoot/system-stop")){foreach($d in @(Get-ChildItem "$RuntimeRoot/Attempts" -Directory -ErrorAction SilentlyContinue)){if(!(Test-Path "$($d.FullName)/runtime.Observe.desktop-process.json")){continue};$o=Get-Content "$($d.FullName)/owner.json" -Raw|ConvertFrom-Json;if([IO.Path]::GetFullPath($o.storage) -eq [IO.Path]::GetFullPath($StorageRoot)){$receipt=Get-Content "$($d.FullName)/runtime.Observe.desktop-process.json" -Raw|ConvertFrom-Json;break}};if(!$receipt){Start-Sleep -Milliseconds 100}}
 if(!$receipt -or $receipt.inputDesktopActive -or $receipt.exe -ne $ExpectedExe){throw 'Owned inactive Player required'};$playerPid=$receipt.pid;$proc=Get-Process -Id $playerPid;if($proc.Path -ne $ExpectedExe){throw 'PID identity mismatch'};$iteration=0
 while(!(Test-Path "$StorageRoot/system-stop") -and [datetime]::UtcNow -lt $end){$proc.Refresh();if($proc.HasExited){break}
  foreach($counter in @('Dedicated Usage','Shared Usage','Total Committed')){
   $errors=@();$output=@(Get-Counter -Counter ('\GPU Process Memory(*)\'+$counter) -MaxSamples 2 -ErrorAction Continue -ErrorVariable +errors)
   $all=@($output|ForEach-Object {$_.CounterSamples}|Select-Object Path,InstanceName,CookedValue,RawValue,Status,Timestamp,CounterType)
   @{utc=[datetime]::UtcNow.ToString('o');api='PDH-two-consecutive-samples-all-status-and-errors';pid=$playerPid;counter=$counter;allSamples=$all;targetSamples=@($all|Where-Object InstanceName -match ('^pid_'+$playerPid+'_'));errors=@($errors|ForEach-Object {@{message=$_.ToString();exception=$_.Exception.ToString();category=$_.CategoryInfo.ToString();id=$_.FullyQualifiedErrorId;scriptStack=$_.ScriptStackTrace}});scope='No error filtering: valid PID samples are separate from invalid foreign/target samples'}|ConvertTo-Json -Depth 7 -Compress|Add-Content "$OutputRoot/gpu-diagnostic-pdh.jsonl"
  }
  if($iteration -lt 4){$query="Name LIKE 'pid_$($playerPid)_%'";try{$filtered=@(Get-CimInstance Win32_PerfFormattedData_GPUPerformanceCounters_GPUProcessMemory -Filter $query);$all=@(Get-CimInstance Win32_PerfFormattedData_GPUPerformanceCounters_GPUProcessMemory);@{utc=[datetime]::UtcNow.ToString('o');pid=$playerPid;filter=$query;filtered=@($filtered|Select-Object Name,DedicatedUsage,SharedUsage,TotalCommitted);clientMatched=@($all|Where-Object Name -match ('^pid_'+$playerPid+'_')|Select-Object Name,DedicatedUsage,SharedUsage,TotalCommitted);allNames=@($all.Name);scope='Sequential same-process filter versus unfiltered/client-side comparison; cache timestamps may differ'}|ConvertTo-Json -Depth 6 -Compress|Add-Content "$OutputRoot/gpu-diagnostic-wmi.jsonl"}catch{@{utc=[datetime]::UtcNow.ToString('o');pid=$playerPid;error=$_.Exception.ToString()}|ConvertTo-Json -Compress|Add-Content "$OutputRoot/gpu-diagnostic-wmi.jsonl"}}
  $iteration++;Start-Sleep -Milliseconds 1000
 };@{status='PASS';pid=$playerPid;iterations=$iteration;scope='Diagnostic collection completed, per-sample availability is separate; no setting/service changes'}|ConvertTo-Json|Set-Content "$OutputRoot/receipt.json"
}catch{$_|Out-String|Set-Content "$OutputRoot/error.txt";exit 1}
